    max_count = 0
    max_hour = None

    for time in data:
        hour = extract_hour(time)
        if hour:
            hours.add(hour)

    for hour in hours:
        count = count_on_time(data, hour)
        if count > max_count:
            max_count = count
            max_hour = hour

    return max_hour, max_count

